import { useState, useEffect } from 'react'
import { Settings, Trash2, Save, FolderOpen, Info, FolderSearch, Eye, EyeOff, Key, CheckCircle } from 'lucide-react'
import { getConfig, updateProjectDirs, saveClaudeApiKey, getClaudeApiKeyStatus } from '../lib/api'
import { useApi } from '../hooks/useApi'
import DirectoryPicker from '../components/DirectoryPicker'

interface Props {
  onSave: () => void
}

export default function SettingsPage({ onSave }: Props) {
  const { data: config, loading } = useApi(getConfig)
  const { data: apiKeyStatus, refetch: refetchKeyStatus } = useApi(getClaudeApiKeyStatus)
  const [dirs, setDirs] = useState<string[]>([])
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)
  const [pickerOpen, setPickerOpen] = useState(false)
  const [apiKey, setApiKey] = useState('')
  const [showApiKey, setShowApiKey] = useState(false)
  const [savingKey, setSavingKey] = useState(false)
  const [keySaved, setKeySaved] = useState(false)

  useEffect(() => {
    if (config) {
      setDirs(config.projectDirs || [])
      setDirty(false)
    }
  }, [config])

  const handleSaveApiKey = async () => {
    if (!apiKey.trim()) return
    setSavingKey(true)
    try {
      await saveClaudeApiKey(apiKey.trim())
      setApiKey('')
      setKeySaved(true)
      refetchKeyStatus()
      setTimeout(() => setKeySaved(false), 3000)
    } finally {
      setSavingKey(false)
    }
  }

  const handleAddFromPicker = (dirPath: string) => {
    const display = dirPath.replace(/^\/Users\/[^/]+/, '~')
    if (!dirs.includes(dirPath) && !dirs.includes(display)) {
      setDirs([...dirs, display])
      setDirty(true)
    }
  }

  const handleRemove = (index: number) => {
    setDirs(dirs.filter((_, i) => i !== index))
    setDirty(true)
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      await updateProjectDirs(dirs)
      setDirty(false)
      onSave()
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-3xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Settings className="w-6 h-6 text-text-secondary" />
            Settings
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            Configure Claude Hub
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={!dirty || saving}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Save className="w-4 h-4" />
          {saving ? 'Saving...' : 'Save'}
        </button>
      </div>

      {/* Info */}
      <div className="bg-accent-muted border border-accent/20 rounded-xl p-4 mb-6 flex items-start gap-3">
        <Info className="w-5 h-5 text-accent shrink-0 mt-0.5" />
        <div className="text-sm text-accent-hover">
          <p className="font-medium mb-1">How project discovery works</p>
          <p className="text-text-secondary">
            Add parent directories below. Claude Hub scans each directory for subdirectories
            containing <code className="text-accent font-mono text-xs">.claude/</code>,{' '}
            <code className="text-accent font-mono text-xs">CLAUDE.md</code>, or{' '}
            <code className="text-accent font-mono text-xs">package.json</code>.
          </p>
        </div>
      </div>

      {/* Claude directory info */}
      <div className="bg-surface border border-border rounded-xl p-5 mb-6">
        <div className="flex items-center gap-3">
          <FolderOpen className="w-5 h-5 text-text-muted" />
          <div>
            <p className="text-sm font-medium">Claude Directory</p>
            <p className="text-xs text-text-muted font-mono">{config?.claudeDir}</p>
          </div>
          <span
            className={`ml-auto text-xs px-2 py-1 rounded-md ${
              config?.claudeDirExists
                ? 'bg-green-muted text-green'
                : 'bg-red-muted text-red'
            }`}
          >
            {config?.claudeDirExists ? 'Found' : 'Not found'}
          </span>
        </div>
      </div>

      {/* Project Directories */}
      <div className="bg-surface border border-border rounded-xl p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold">Project Directories</h2>
          <button
            onClick={() => setPickerOpen(true)}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
          >
            <FolderSearch className="w-4 h-4" />
            Browse & Add
          </button>
        </div>

        {/* List */}
        {dirs.length === 0 ? (
          <div className="py-8 text-center">
            <FolderOpen className="w-10 h-10 text-text-muted mx-auto mb-3" />
            <p className="text-text-secondary font-medium">No directories configured</p>
            <p className="text-text-muted text-sm mt-1">
              Click "Browse & Add" to select folders containing your projects
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {dirs.map((dir, i) => (
              <div
                key={i}
                className="flex items-center justify-between bg-surface-2 rounded-lg px-4 py-3 group"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <FolderOpen className="w-4 h-4 text-text-muted shrink-0" />
                  <span className="text-sm font-mono text-text-secondary truncate">{dir}</span>
                </div>
                <button
                  onClick={() => handleRemove(i)}
                  className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted transition-colors opacity-0 group-hover:opacity-100"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Directory Picker Modal */}
      <DirectoryPicker
        open={pickerOpen}
        onClose={() => setPickerOpen(false)}
        onSelect={handleAddFromPicker}
        existingDirs={dirs}
      />
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Save, ArrowLeft, RotateCcw, Bot } from 'lucide-react'
import {
  getGlobalAgent,
  updateGlobalAgent,
  getProjectAgent,
  updateProjectAgent,
} from '../lib/api'

interface Props {
  scope: 'global' | 'project'
}

export default function AgentEditor({ scope }: Props) {
  const { name, projectId } = useParams()
  const navigate = useNavigate()
  const [content, setContent] = useState('')
  const [originalContent, setOriginalContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      try {
        const agent =
          scope === 'global'
            ? await getGlobalAgent(name!)
            : await getProjectAgent(projectId!, name!)
        setContent(agent.raw)
        setOriginalContent(agent.raw)
      } catch {
        setContent('')
        setOriginalContent('')
      }
      setLoading(false)
    }
    load()
  }, [name, projectId, scope])

  const handleSave = async () => {
    setSaving(true)
    try {
      if (scope === 'global') {
        await updateGlobalAgent(name!, content)
      } else {
        await updateProjectAgent(projectId!, name!, content)
      }
      setOriginalContent(content)
      setDirty(false)
    } finally {
      setSaving(false)
    }
  }

  const backPath = scope === 'global' ? '/global/agents' : `/projects/${projectId}`

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-5xl h-screen flex flex-col">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate(backPath)}
            className="p-2 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
              <Bot className="w-6 h-6 text-purple" />
              {name}
            </h1>
            <p className="text-text-secondary text-sm mt-0.5">
              {scope === 'global' ? 'Global agent' : 'Project agent'} — Edit raw markdown
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {dirty && (
            <button
              onClick={() => {
                setContent(originalContent)
                setDirty(false)
              }}
              className="flex items-center gap-2 px-3 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              Reset
            </button>
          )}
          <button
            onClick={handleSave}
            disabled={!dirty || saving}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <Save className="w-4 h-4" />
            {saving ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <textarea
          value={content}
          onChange={(e) => {
            setContent(e.target.value)
            setDirty(true)
          }}
          className="w-full h-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors"
          placeholder="---&#10;name: Agent Name&#10;description: What this agent does&#10;model: sonnet&#10;---&#10;&#10;Agent instructions..."
          spellCheck={false}
        />
      </div>
    </div>
  )
}

