import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Save, ArrowLeft, RotateCcw, ShieldCheck, Info, Sparkles } from 'lucide-react'
import { getProjectRule, updateProjectRule } from '../lib/api'
import AiAssistant from '../components/AiAssistant'

export default function RuleEditor() {
  const { projectId, name } = useParams()
  const navigate = useNavigate()
  const [content, setContent] = useState('')
  const [originalContent, setOriginalContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)
  const [isNew, setIsNew] = useState(false)
  const [aiOpen, setAiOpen] = useState(false)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      try {
        const rule = await getProjectRule(projectId!, name!)
        setContent(rule.content)
        setOriginalContent(rule.content)
      } catch {
        setContent('')
        setOriginalContent('')
        setIsNew(true)
      }
      setLoading(false)
    }
    load()
  }, [name, projectId])

  const handleSave = async () => {
    setSaving(true)
    try {
      await updateProjectRule(projectId!, name!, content)
      setOriginalContent(content)
      setDirty(false)
      setIsNew(false)
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-5xl h-screen flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate(`/projects/${projectId}`)}
            className="p-2 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
              <ShieldCheck className="w-6 h-6 text-green" />
              {name}
            </h1>
            <p className="text-text-secondary text-sm mt-0.5">
              {isNew ? 'New rule' : 'Edit rule'} — Constraint Claude must follow
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setAiOpen(true)}
            className="flex items-center gap-2 px-3 py-2 text-sm font-medium text-purple bg-purple-muted rounded-lg hover:opacity-80 transition-colors"
          >
            <Sparkles className="w-4 h-4" />
            AI Assist
          </button>
          {dirty && (
            <button
              onClick={() => {
                setContent(originalContent)
                setDirty(false)
              }}
              className="flex items-center gap-2 px-3 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              Reset
            </button>
          )}
          <button
            onClick={handleSave}
            disabled={!dirty || saving}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <Save className="w-4 h-4" />
            {saving ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>

      {/* Help */}
      <div className="bg-green-muted border border-green/20 rounded-xl p-4 mb-4 flex items-start gap-3">
        <Info className="w-4 h-4 text-green shrink-0 mt-0.5" />
        <div className="text-xs text-text-secondary">
          <p className="font-medium text-green mb-1">How rules work</p>
          <p>
            Rules are constraints Claude must always follow in this project.
            Each rule file is loaded automatically. Write clear, specific instructions.
            Example: "Always use TypeScript strict mode" or "Never commit .env files".
          </p>
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <textarea
          value={content}
          onChange={(e) => {
            setContent(e.target.value)
            setDirty(true)
          }}
          className="w-full h-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors"
          placeholder={`# ${name}\n\nWrite your rule here. Be specific and clear.\n\nExample:\n- Always use the project's logger utility instead of console.log\n- All API responses must include proper error handling\n- Never hardcode credentials or API keys`}
          spellCheck={false}
        />
      </div>
    </div>
  )
}

