app.post('/api/copy-agent', (req, res) => {
  const { from, to, agentName } = req.body;
  if (!isValidName(agentName)) return res.status(400).json({ error: 'Invalid agent name' });

  let srcPath, destDir;
  if (from === 'global') {
    srcPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
  } else {
    const fromPath = resolveProjectPath(from);
    if (!fromPath) return res.status(400).json({ error: 'Invalid source project' });
    srcPath = path.join(fromPath, '.claude', 'agents', agentName + '.md');
  }
  if (to === 'global') {
    destDir = path.join(CLAUDE_DIR, 'agents');
  } else {
    const toPath = resolveProjectPath(to);
    if (!toPath) return res.status(400).json({ error: 'Invalid target project' });
    destDir = path.join(toPath, '.claude', 'agents');
  }
  ensureDir(destDir);
  const content = readFileSafe(srcPath);
  if (!content) return res.status(404).json({ error: 'Source agent not found' });
  fs.writeFileSync(path.join(destDir, agentName + '.md'), content);
  res.json({ ok: true });
});

app.post('/api/move-agent', (req, res) => {
  const { from, to, agentName } = req.body;
  if (!isValidName(agentName)) return res.status(400).json({ error: 'Invalid agent name' });

  let srcPath, destDir;
  if (from === 'global') {
    srcPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
  } else {
    const fromPath = resolveProjectPath(from);
    if (!fromPath) return res.status(400).json({ error: 'Invalid source project' });
    srcPath = path.join(fromPath, '.claude', 'agents', agentName + '.md');
  }
  if (to === 'global') {
    destDir = path.join(CLAUDE_DIR, 'agents');
  } else {
    const toPath = resolveProjectPath(to);
    if (!toPath) return res.status(400).json({ error: 'Invalid target project' });
    destDir = path.join(toPath, '.claude', 'agents');
  }
  ensureDir(destDir);
  const content = readFileSafe(srcPath);
  if (!content) return res.status(404).json({ error: 'Source agent not found' });
  fs.writeFileSync(path.join(destDir, agentName + '.md'), content);
  if (fs.existsSync(srcPath)) fs.unlinkSync(srcPath);
  res.json({ ok: true });
});

// Claude AI chat — uses local `claude` CLI (no API key required)
const { spawn } = require('child_process');

app.post('/api/ai/chat', (req, res) => {
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  // Build a single prompt from the conversation history
  const systemText = system || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical. When asked to write or improve content, respond with the full improved content ready to use.';

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') {
      prompt += `User: ${msg.content}\n\n`;
    } else if (msg.role === 'assistant') {
      prompt += `Assistant: ${msg.content}\n\n`;
    }
  }
  prompt += 'Assistant:';

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const proc = spawn(claudePath, ['-p', prompt], {
    env: { ...process.env, HOME: os.homedir() },
    timeout: 60000,
  });

  let output = '';
  let errOutput = '';

  proc.stdout.on('data', (data) => { output += data.toString(); });
  proc.stderr.on('data', (data) => { errOutput += data.toString(); });

  proc.on('close', (code) => {
    if (code !== 0) {
      return res.status(500).json({ error: errOutput || `claude exited with code ${code}` });
    }
    res.json({ content: output.trim() });
  });

  proc.on('error', (err) => {
    res.status(500).json({ error: `Failed to run claude: ${err.message}` });
  });
});

