                    </button>
                  </div>
                )}
              </div>
            </div>
          ))}

          {loading && (
            <div className="flex gap-2.5 justify-start">
              <div className="w-6 h-6 rounded-md bg-purple-muted flex items-center justify-center shrink-0 mt-0.5">
                <RefreshCw className="w-3.5 h-3.5 text-purple animate-spin" />
              </div>
              <div className="bg-surface-2 rounded-xl rounded-bl-sm px-3.5 py-2.5">
                <div className="flex gap-1.5 items-center h-5">
                  <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:0ms]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:150ms]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-text-muted animate-bounce [animation-delay:300ms]" />
                </div>
              </div>
            </div>
          )}

          {error && (
            <div className="bg-red-muted border border-red/20 rounded-xl px-4 py-3 text-sm text-red">
              {error}
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="px-4 py-4 border-t border-border shrink-0">
          <div className="flex gap-2 items-end">
            <textarea
              ref={inputRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={`Ask Claude about your ${label}...`}
              rows={2}
              className="flex-1 bg-surface-2 border border-border rounded-xl px-3.5 py-2.5 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted"
            />
            <button
              onClick={send}
              disabled={!input.trim() || loading}
              className="p-2.5 bg-accent text-white rounded-xl hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors shrink-0"
            >
              <Send className="w-4 h-4" />
            </button>
          </div>
          <p className="text-[11px] text-text-muted mt-2">
            Enter to send · Shift+Enter for new line
          </p>
        </div>
      </div>
    </div>
  )
}

function getSuggestions(context: AiContext): string[] {
  switch (context) {
    case 'agent':
      return [
        'Write a complete agent for code review',
        'Improve my current agent description',
        'What tools should this agent use?',
        'Make the instructions more specific',
      ]
    case 'command':
      return [
        'Write a command to generate unit tests',
        'Improve this command to be more specific',
        'How should I use $ARGUMENTS here?',
        'Write a PR description command',
      ]
    case 'rule':
      return [
        'Write rules for a React TypeScript project',
        'Add a rule about code style',
        'What rules help Claude work better?',
        'Improve clarity of my current rules',
      ]
    case 'claude-md':
      return [
        'Write a CLAUDE.md for a Next.js project',
        'Add tech stack section',
        'Improve the architecture description',
        'What should every CLAUDE.md include?',
      ]
  }
}

