import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Save, ArrowLeft, RotateCcw, Terminal, Info } from 'lucide-react'
import { getProjectCommand, updateProjectCommand } from '../lib/api'

export default function CommandEditor() {
  const { projectId, name } = useParams()
  const navigate = useNavigate()
  const [content, setContent] = useState('')
  const [originalContent, setOriginalContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)
  const [isNew, setIsNew] = useState(false)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      try {
        const cmd = await getProjectCommand(projectId!, name!)
        setContent(cmd.content)
        setOriginalContent(cmd.content)
      } catch {
        // New command
        setContent('')
        setOriginalContent('')
        setIsNew(true)
      }
      setLoading(false)
    }
    load()
  }, [name, projectId])

  const handleSave = async () => {
    setSaving(true)
    try {
      await updateProjectCommand(projectId!, name!, content)
      setOriginalContent(content)
      setDirty(false)
      setIsNew(false)
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-5xl h-screen flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate(`/projects/${projectId}`)}
